BEGIN;
CREATE SCHEMA access_test;
CREATE FUNCTION access_test.assert(ok boolean,msg text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'ASSERT: %',msg;END IF;END $$;
CREATE FUNCTION access_test.denied(statement text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE statement;EXCEPTION WHEN OTHERS THEN RETURN;END;RAISE EXCEPTION 'Expected rejection: %',statement;END $$;
GRANT USAGE ON SCHEMA access_test TO authenticated,anon;GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA access_test TO authenticated,anon;
SELECT access_test.assert((SELECT full_module_access AND maintenance_role='analista_transporte' FROM public.company_members WHERE user_id='29000000-0000-4000-8000-000000000092'),'existing unlinked account repaired without changing profile');
INSERT INTO auth.users(id,email) SELECT ('29000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'access-'||n||'@example.invalid' FROM generate_series(1,7)n;
INSERT INTO public.companies(id,nome,created_by) VALUES('19000000-0000-4000-8000-000000000001','Access fixture','29000000-0000-4000-8000-000000000001'),('19000000-0000-4000-8000-000000000002','Other access fixture','29000000-0000-4000-8000-000000000001');
INSERT INTO public.company_members(company_id,user_id,role,maintenance_role,created_by) SELECT '19000000-0000-4000-8000-000000000001',('29000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'auditor',(ARRAY['admin_geral','admin_empresa','analista_transporte','supervisor','operador_logistico','motorista','cliente'])[n],'29000000-0000-4000-8000-000000000001' FROM generate_series(1,7)n;
INSERT INTO public.veiculos(id,company_id,placa,tipo,marca_modelo,km_atual) VALUES('39000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000001','ACS0001','caminhao','Access fixture',1000);
SET LOCAL ROLE authenticated;
DO $$ DECLARE n integer;actor uuid;BEGIN FOR n IN 1..7 LOOP actor:=('29000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 PERFORM access_test.assert(maintenance_private.partner_access('19000000-0000-4000-8000-000000000001',true),'all profiles can manage maintenance');
 PERFORM access_test.assert(maintenance_private.can_access_company('19000000-0000-4000-8000-000000000001',true),'all profiles can write company fleet');
 PERFORM access_test.assert(NOT maintenance_private.is_limited_actor(),'released users see legacy modules');
 PERFORM access_test.assert(NOT maintenance_private.partner_access('19000000-0000-4000-8000-000000000002',true),'no cross-company access');
 PERFORM public.maintenance_analytics_command('19000000-0000-4000-8000-000000000001','context',jsonb_build_object('start',current_date-30,'end',current_date));
 PERFORM public.maintenance_plan_command('19000000-0000-4000-8000-000000000001','context');
 PERFORM public.maintenance_vehicle_command('19000000-0000-4000-8000-000000000001','options');
 PERFORM public.maintenance_communication_command('19000000-0000-4000-8000-000000000001','config');
 PERFORM public.maintenance_partner_requests_command('19000000-0000-4000-8000-000000000001','list');
 END LOOP;END $$;
INSERT INTO public.maintenance_partners(id,company_id,razao_social) VALUES('49000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000001','Client-created workshop');
SELECT access_test.assert((SELECT created_by=auth.uid() FROM public.maintenance_partners WHERE id='49000000-0000-4000-8000-000000000001'),'client profile creates partner with audit');
SELECT set_config('access_test.order',public.maintenance_order_command('19000000-0000-4000-8000-000000000001','create','{"vehicle_id":"39000000-0000-4000-8000-000000000001","partner_id":"49000000-0000-4000-8000-000000000001","tipo":"corretiva","prioridade":"media","descricao_problema":"Released profile order","km_abertura":1000}')->>'id',true);
SELECT public.maintenance_order_command('19000000-0000-4000-8000-000000000001','item_save',jsonb_build_object('id',current_setting('access_test.order'),'version',(SELECT version FROM public.maintenance_orders WHERE id=current_setting('access_test.order')::uuid),'tipo','servico','descricao','Repair','quantidade',1,'valor_unitario',100));
SELECT access_test.assert((SELECT valor_total=100 FROM public.maintenance_orders WHERE id=current_setting('access_test.order')::uuid),'released client can manage budget items');
SELECT access_test.denied($q$SELECT public.maintenance_vehicle_command('19000000-0000-4000-8000-000000000002','options')$q$);
SELECT access_test.denied($q$UPDATE public.company_members SET full_module_access=true$q$);
RESET ROLE;
UPDATE public.company_members SET ativo=false WHERE user_id='29000000-0000-4000-8000-000000000007';
SET LOCAL ROLE authenticated;
SELECT access_test.assert(NOT maintenance_private.partner_access('19000000-0000-4000-8000-000000000001',true),'inactive membership remains denied');
RESET ROLE;
UPDATE public.company_members SET ativo=true,full_module_access=false WHERE user_id='29000000-0000-4000-8000-000000000007';
SET LOCAL ROLE authenticated;
SELECT access_test.assert(NOT maintenance_private.partner_access('19000000-0000-4000-8000-000000000001'),'explicit restricted membership keeps old role policy');
RESET ROLE;SELECT set_config('request.jwt.claim.sub','',true);SET LOCAL ROLE anon;
SELECT access_test.denied($q$SELECT * FROM public.maintenance_partners$q$);
SELECT access_test.denied($q$SELECT maintenance_private.module_role(NULL::public.company_members)$q$);
RESET ROLE;ROLLBACK;
